INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question_text, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, image_url, is_active)
VALUES
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which of the following is a CHEMICAL change?', 'Dissolving sugar in water', 'Melting ice cream', 'Cutting paper', 'Rotting of tomatoes', 'D', 'Rotting is a biological decomposition process driven by microbial enzymes that breaks down organic molecules into fundamentally new substances with distinct odors and chemical properties. Dissolving sugar, melting ice cream (a phase transition), and cutting paper alter only spatial distribution, physical state, or macroscopic shape without rearranging chemical bonds.', 'assets/illustrations/term1/t1_q1.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which shows ONLY a PHYSICAL change?', 'Crushing chunks of ice', 'Rusting of iron', 'Burning wood', 'Milk turning sour', 'A', 'Crushing ice alters only its macroscopic grain size and total exposed surface area; chemically, it remains H2O. Conversely, rusting oxidizes metallic iron into iron oxide (Fe2O3), burning combusts cellulose into CO2, H2O, and ash, and souring milk ferments lactose into lactic acid—all creating brand-new chemical compounds.', 'assets/illustrations/term1/t1_q2.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What is the MAIN difference between chemical and physical change?', 'Physical change cannot be reversed', 'Physical change always releases heat', 'Chemical change produces a NEW substance', 'Chemical change is always faster', 'C', 'The deﬁning criterion separating chemical transformations from physical ones is the reorganization of atomic bonds to create new chemical identities with different intrinsic properties. Physical changes preserve intramolecular bonds, changing only intermolecular spacing, phase, or mechanical form.', 'assets/illustrations/term1/t1_q3.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which of these is a CHEMICAL change?', 'Opening a soda can', 'Photosynthesis in plants', 'Painting wood', 'Bending metal', 'B', 'Photosynthesis is an endothermic biosynthetic reaction where light energy drives the chemical transformation of carbon dioxide and water into glucose and molecular oxygen (6 CO2 + 6 H2O → C6H12O6 + 6 O2). Opening a can releases pressurized gas, painting adds a surface layer, and bending metal is mechanical deformation.', 'assets/illustrations/term1/t1_q4.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Bubbles forming when vinegar is mixed with baking soda is evidence of:', 'Evolution of gas', 'Color change', 'Physical change only', 'Precipitate formation', 'A', 'Effervescence (rapid bubble evolution) conﬁrms the generation of a gaseous product that escapes the liquid phase. The reaction between acetic acid (CH3COOH) and sodium bicarbonate (NaHCO3) yields carbon dioxide gas (CO2), sodium acetate, and water.', 'assets/illustrations/term1/t1_q5.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Curdling of milk into lumpy solids is an example of which evidence?', 'Temperature drop only', 'Gas evolution', 'Production of light', 'Formation of a precipitate', 'D', 'A precipitate is an insoluble solid that emerges from a liquid mixture during a chemical transformation. When milk is acidiﬁed, casein proteins denature and aggregate, falling out of colloidal suspension to form solid curds.', 'assets/illustrations/term1/t1_q6.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Mixing quicklime and water makes the container feel hot. What evidence is this?', 'Color change', 'Change in temperature', 'Gas formation', 'Precipitate formation', 'B', 'The marked generation of heat signiﬁes an exothermic chemical reaction (CaO + H2O → Ca(OH)2 + heat). The measurable temperature increase is direct thermodynamic evidence of bond formation and net enthalpy release.', 'assets/illustrations/term1/t1_q7.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which is NOT evidence that a chemical reaction occurred?', 'Production of light (like burning)', 'Formation of gas bubbles', 'Change in shape only by cutting', 'Change in color', 'C', 'Cutting modiﬁes solely the exterior geometric boundary and surface dimensions of an object. Primary empirical indicators of chemical change include spontaneous luminescence, evolution of gas, persistent color shift, and unexpected temperature ﬂuctuations.', 'assets/illustrations/term1/t1_q8.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'A student mixes two clear liquids and a yellow solid settles at the bottom. This is:', 'Precipitate formation', 'Physical change', 'Gas evolution', 'Boiling', 'A', 'When ions from two separate soluble aqueous solutions combine to synthesize an insoluble ionic compound that separates from the liquid matrix and settles, that insoluble substance is deﬁned as a chemical precipitate (such as combining clear Pb(NO3)2 and KI to yield solid PbI2).', 'assets/illustrations/term1/t1_q9.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'In a chemical equation, substances on the LEFT side of the arrow are called:', 'Coeﬃcients', 'Products', 'Precipitates', 'Reactants', 'D', 'Standard chemical notation designates the starting chemical species positioned to the left of the reaction arrow as reactants. They represent the initial matter that participates in and is consumed during the reaction.', 'assets/illustrations/term1/t1_q10.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Substances written on the RIGHT side of the arrow are:', 'Symbols only', 'Products', 'Reactants', 'Gases always', 'B', 'By chemical convention, the right side of the reaction arrow speciﬁes the products—the newly synthesized compounds or elemental species resulting from the chemical rearrangement of the reactants.', 'assets/illustrations/term1/t1_q11.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What does the symbol (aq) mean in a chemical equation?', 'Solid precipitate', 'Gaseous state', 'Dissolved in water (aqueous)', 'Liquid pure substance', 'C', 'The notation (aq) denotes an aqueous solution (from Latin aqua), designating that the chemical substance is dissolved in water as the solvent. This is distinct from (l), which denotes a pure liquid substance.', 'assets/illustrations/term1/t1_q12.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'The symbol Δ written above the arrow means:', 'Heat is supplied to the reaction', 'Gas is released', 'A precipitate forms', 'Reaction is reversible', 'A', 'The Greek capital letter delta (Δ) inscribed above or below the reaction arrow indicates that thermal energy (heat) must be applied to drive the endothermic reaction forward.', 'assets/illustrations/term1/t1_q13.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'The downward arrow ( ↓ ) next to a product means:', 'Heat released', 'Gas evolved', 'Liquid product', 'A solid precipitate was formed', 'D', 'In classical chemical notation, a downward arrow ( ↓ ) positioned next to a formula denotes that the substance is an insoluble solid precipitate that settles down out of solution. In contrast, an upward arrow ( ↑ ) signiﬁes gas evolution.', 'assets/illustrations/term1/t1_q14.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What does the + sign between reactants mean?', 'Heat is added', 'Substances are mixed / added together', '"Yields" or "produces"', 'Only one reacts', 'B', 'The plus sign (+) separating reactants functions as a connector meaning “reacts with” or indicates that the chemical substances are added/combined together in the reaction system. The arrow ( → ) denotes “yields” or “produces.”', 'assets/illustrations/term1/t1_q15.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which general equation represents COMBINATION (Synthesis)?', 'AB + CD → AD + CB', 'A + B → AB', 'AB → A + B', 'AB + C → AC + B', 'B', 'In a synthesis or combination reaction, multiple simple substances (A and B) join together to create a single, more complex compound (AB).', 'assets/illustrations/term1/t1_q16.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', '2Na + Cl2 → 2NaCl is an example of:', 'Single displacement', 'Combustion', 'Decomposition', 'Combination Synthesis Rxn', 'D', 'Sodium metal and chlorine gas react directly to form a single product, sodium chloride (table salt), characteristic of combination.', 'assets/illustrations/term1/t1_q17.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'The reaction CaCO3 → CaO + CO2 is classified as:', 'Combination', 'Double displacement', 'Decomposition', 'Acid-base reaction', 'C', 'Calcium carbonate splits under heat into calcium oxide and carbon dioxide gas, which fits the definition of decomposition.', 'assets/illustrations/term1/t1_q18.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What is the general form of DECOMPOSITION?', 'AB + C → AC + B', 'Acid + Base → Salt + Water', 'A + B → AB', 'AB → A + B', 'D', 'Decomposition starts with one single compound (AB) breaking down into multiple separate products (A + B).', 'assets/illustrations/term1/t1_q19.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Pb + FeSO4 → PbSO4 + Fe is which type?', 'Single displacement', 'Double displacement', 'Combustion', 'Decomposition Single Swap', 'A', 'Lead (Pb) kicks out iron (Fe) from iron sulfate to bond with sulfate, leaving iron by itself. This is a single replacement reaction.', 'assets/illustrations/term1/t1_q20.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'In SINGLE DISPLACEMENT, what happens?', 'Ions of two compounds swap', 'One element replaces another element in a compound', 'One compound splits into two', 'Oxygen reacts with a hydrocarbon', 'B', 'A single uncombined element steps in and displaces an element inside an existing compound.', 'assets/illustrations/term1/t1_q21.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'AgNO3 + NaCl → AgCl↓ + NaNO3 is:', 'Decomposition', 'Combination', 'Double displacement', 'Single displacement Double Swap', 'C', 'Both reactant compounds trade ions: silver pairs with chlorine (forming a precipitate), and sodium pairs with nitrate.', 'assets/illustrations/term1/t1_q22.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Which is ALWAYS a reactant in COMBUSTION reactions?', 'Water', 'Nitrogen', 'Carbon dioxide', 'Oxygen gas (O2) O ₂  + Fuel', 'D', 'By definition, burning or combustion is a chemical reaction that requires an oxidant, most commonly atmospheric oxygen gas.', 'assets/illustrations/term1/t1_q23.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Combustion of a hydrocarbon always produces these two products:', 'Carbon dioxide (CO2) and Water (H2O)', 'Oxygen and hydrogen', 'Salt and water', 'Metal oxide and gas', 'A', 'Complete combustion of compounds containing only carbon and hydrogen yields carbon dioxide and water vapor.', 'assets/illustrations/term1/t1_q24.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'HBr + NaOH → NaBr + H2O is an example of:', 'Combustion', 'Acid-Base / Neutralization', 'Decomposition', 'Single displacement Acid + Base', 'B', 'Hydrobromic acid (HBr) reacts with sodium hydroxide (base) to form sodium bromide (salt) and water.', 'assets/illustrations/term1/t1_q25.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Neutralization is a special type of:', 'Decomposition', 'Combination', 'Combustion', 'Double displacement Ion Exchange', 'D', 'Acid-base reactions involve the reciprocal swapping of ions between two compounds, categorizing them as double displacement reactions.', 'assets/illustrations/term1/t1_q26.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Which change is reversible and only alters form?', 'Digesting food', 'Tarnishing silver', 'Melting wax', 'Burning wood Phase Change', 'C', 'Melting wax alters state from solid to liquid without changing its chemical composition, making it easily reversible by cooling.', 'assets/illustrations/term1/t1_q27.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Which observation does NOT suggest a chemical change?', 'Permanent color change', 'Light and heat given off', 'Salt dissolving in water', 'New solid not easily separated Dissolving', 'C', 'Dissolving creates a solution where no new chemical bonds are made; evaporating the water recovers the original salt.', 'assets/illustrations/term1/t1_q28.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'In the equation Mg + O2 → MgO, what is magnesium oxide?', 'Catalyst', 'Product', 'Gas', 'Reactant Right Side', 'B', 'Substances written to the right of the reaction arrow represent what is created, termed products.', 'assets/illustrations/term1/t1_q29.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Which reaction type is: Fuel + O2 → CO2 + H2O?', 'Decomposition', 'Synthesis', 'Single displacement', 'Combustion Burning', 'D', 'The presence of fuel reacting with oxygen to release carbon dioxide and water defines combustion.', 'assets/illustrations/term1/t1_q30.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'What does the arrow (→) mean in a chemical equation?', 'Reacts with', 'Yields / produces', 'Dissolves in', 'Equals Yields', 'B', 'The directional arrow points from the starting materials toward the newly formed products.', 'assets/illustrations/term1/t1_q31.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Which is a decomposition reaction?', 'Zn + 2HCl → ZnCl2 + H2', '2H2 + O2 → 2H2O', '2H2O2 → 2H2O + O2', 'NaOH + HCl → NaCl + H2O', 'C', 'Hydrogen peroxide breaks down into water and oxygen gas, showing one reactant splitting into multiple components.', 'assets/illustrations/term1/t1_q32.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'A reaction where two compounds exchange ions is called:', 'Double displacement', 'Single displacement', 'Decomposition', 'Synthesis Exchange', 'A', 'In a double displacement reaction, the positive and negative ions of two ionic compounds switch places.', 'assets/illustrations/term1/t1_q33.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Which is an example of synthesis?', 'Sodium chloride + Silver nitrate → Silver chloride + Sodium nitrate', 'Water → Hydrogen + Oxygen', 'Iron + Sulfur → Iron sulfide', 'Wood + Oxygen → Ash + CO2', 'C', 'Iron and sulfur heat together to make iron sulfide, a classic two-reactants-to-one-product synthesis.', 'assets/illustrations/term1/t1_q34.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Which symbol shows a gaseous product?', '(l)', '(aq)', '(s)', '(g) or ↑ Gas / Up', 'D', 'State symbols use (g) or an upward arrow (↑) to signify that a substance is evolved as a gas.', 'assets/illustrations/term1/t1_q35.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'When metal is heated and glows red, but returns to original properties upon cooling, this is a:', 'Chemical change', 'Physical change', 'Decomposition reaction', 'Combustion reaction Thermal', 'B', 'Temperature changes alone do not create new chemical substances if the original properties return upon cooling.', 'assets/illustrations/term1/t1_q36.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Which equation correctly represents a neutralization reaction?', '2H2 + O2 → 2H2O', 'HCl + KOH → KCl + H2O', 'CaCO3 → CaO + CO2', 'Zn + CuSO4 → ZnSO4 + Cu', 'B', 'Neutralization requires pairing an acid and a base to yield a neutral salt and water.', 'assets/illustrations/term1/t1_q37.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'What coefficient is needed for O2 to balance: C3H8 + ?O2 → 3CO2 + 4H2O?', '3', '4', '5', '10', 'C', 'The products contain (3 × 2) = 6 oxygen atoms from CO2 and (4 × 1) = 4 oxygen atoms from water, totaling 10 oxygen atoms. Thus, 5 O2 are needed.', 'assets/illustrations/term1/t1_q38.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'Which of the following is evidence that a chemical reaction has taken place?', 'Melting of ice cubes', 'Boiling water into steam', 'Formation of a precipitate (solid) when solutions mix', 'Dissolving sugar in hot tea Precipitate', 'C', 'The unexpected appearance of a solid precipitate signals that chemical bonds rearranged to create a new insoluble compound.', 'assets/illustrations/term1/t1_q39.svg', true),
  ('b0000000-0000-0000-0000-000000000101', 1, 'post_test', 'In a balanced chemical equation, the total mass of the reactants is always:', 'Greater than the total mass of the products', 'Less than the total mass of the products', 'Equal to the total mass of the products', 'Unrelated to the mass of the products Conservation', 'C', 'Mass remains constant throughout a closed chemical change because atoms are only rearranged, not lost or added.', 'assets/illustrations/term1/t1_q40.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'A + B → AB represents which type of reaction?', 'Single displacement', 'Combustion', 'Combination / Synthesis', 'Decomposition', 'C', 'Two or more simpler reactants combine to form a single, more complex product molecule.', 'assets/illustrations/term1/t2_q1.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'AB → A + B represents which type of reaction?', 'Combination', 'Double displacement', 'Neutralization', 'Decomposition', 'D', 'A single reactant compound breaks down into two or more simpler constituent products.', 'assets/illustrations/term1/t2_q2.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Hydrocarbon + O ₂ → CO ₂ + H ₂ O + heat represents:', 'Combustion', 'Acid-base reaction', 'Precipitation', 'Decomposition', 'A', 'Rapid oxidation of a hydrocarbon fuel in oxygen releases thermal energy, carbon dioxide, and water vapor.', 'assets/illustrations/term1/t2_q3.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Acid + Base → Salt + Water represents:', 'Decomposition', 'Single replacement', 'Neutralization (Special Double Displacement)', 'Combustion', 'C', 'Acidic H ⁺ ions and basic OH ⁻ ions combine to form water while pairing remaining ions into a salt.', 'assets/illustrations/term1/t2_q4.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'AB + C → AC + B represents:', 'Synthesis', 'Decomposition', 'Single Displacement / Replacement', 'Double displacement', 'C', 'A free uncombined element (C) displaces another element (B) from an existing compound (AB).', 'assets/illustrations/term1/t2_q5.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'AB + CD → AD + CB represents:', 'Combination', 'Double Displacement / Replacement', 'Combustion', 'Single displacement', 'B', 'Two ionic compounds exchange partner ions with each other to form two new compounds.', 'assets/illustrations/term1/t2_q6.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', '2Na + Cl ₂ → 2NaCl is an example of:', 'Combustion', 'Single displacement', 'Combination', 'Decomposition', 'C', 'Sodium metal and chlorine gas react directly to form a single ionic product, sodium chloride.', 'assets/illustrations/term1/t2_q7.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'CaCO ₃ → CaO + CO ₂ is an example of:', 'Acid-base reaction', 'Combination', 'Double displacement', 'Decomposition', 'D', 'Limestone absorbs thermal energy to break down into quicklime and carbon dioxide gas.', 'assets/illustrations/term1/t2_q8.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Plants build glucose from CO ₂ + H ₂ O using sunlight. This process is:', 'Corrosion', 'Photosynthesis (Combination / Endothermic)', 'Respiration', 'Combustion', 'B', 'Solar energy powers the synthesis of glucose from simple inorganic molecules, storing chemical energy.', 'assets/illustrations/term1/t2_q9.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Glucose + O ₂ → CO ₂ + H ₂ O + energy in body cells is:', 'Cellular Respiration (Exothermic oxidation)', 'Photosynthesis', 'Decomposition', 'Combustion only', 'A', 'Cells oxidize glucose to release metabolic energy, acting as a controlled biological counterpart to combustion.', 'assets/illustrations/term1/t2_q10.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Which reaction involves one reactant breaking down into many products?', 'Neutralization', 'Single replacement', 'Decomposition', 'Synthesis', 'C', 'Decomposition reactions are characterized by a single starting reactant breaking into multiple components.', 'assets/illustrations/term1/t2_q11.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Rusting of iron is a classic example of:', 'Photosynthesis', 'Neutralization', 'Combustion', 'Oxidation / Corrosion', 'D', 'Metals slowly oxidize when exposed over time to atmospheric oxygen and moisture.', 'assets/illustrations/term1/t2_q12.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Precipitation reactions are characterized by forming:', 'An Insoluble Solid', 'Gas only', 'Water only', 'No new substance', 'A', 'Mixing aqueous solutions can yield an insoluble ionic solid that separates out as a precipitate.', 'assets/illustrations/term1/t2_q13.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'In a single displacement reaction:', 'All substances combine together', 'One element swaps place with another element in a compound', 'One compound splits into multiple parts', 'Nothing changes chemically', 'B', 'An active free element replaces a less active element inside an existing compound structure.', 'assets/illustrations/term1/t2_q14.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Photosynthesis is the chemical reverse of:', 'Acid rain formation', 'Combustion', 'Cellular Respiration', 'Decomposition', 'C', 'Photosynthesis builds glucose from light and CO ₂ , while cellular respiration breaks glucose down to release energy and CO ₂ .', 'assets/illustrations/term1/t2_q15.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Zn + 2HCl → ZnCl ₂ + H ₂ ↑ is classified as:', 'Combination', 'Decomposition', 'Double displacement', 'Single displacement (Metal replaces H in acid)', 'D', 'Active zinc displaces hydrogen from hydrochloric acid to produce zinc chloride and hydrogen gas.', 'assets/illustrations/term1/t2_q16.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'AgNO ₃ + NaCl → AgCl↓ + NaNO ₃ is an example of:', 'Combustion', 'Synthesis', 'Double displacement + Precipitation', 'Single displacement', 'C', 'Cations and anions switch partners, yielding an insoluble silver chloride precipitate.', 'assets/illustrations/term1/t2_q17.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'CH ₄ + 2O ₂ → CO ₂ + 2H ₂ O + heat represents:', 'Neutralization', 'Decomposition', 'Photosynthesis', 'Combustion of Methane (Natural Gas)', 'D', 'Methane reacts rapidly with oxygen to release heat, carbon dioxide, and water vapor.', 'assets/illustrations/term1/t2_q18.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'SO ₂ + NOₓ from industrial and vehicular emissions reacting with rain creates:', 'Ozone layer depletion', 'Freshwater enrichment', 'Acid Rain', 'Neutral water runoff', 'C', 'Non-metal oxides dissolve in atmospheric moisture to form sulfuric and nitric acids.', 'assets/illustrations/term1/t2_q19.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', '4Fe + 3O ₂ + H ₂ O → 2Fe ₂ O ₃ · H ₂ O (Rust) represents:', 'Corrosion / Slow Oxidation', 'Rapid combustion', 'Acid-base neutralization', 'Single displacement', 'A', 'Iron reacts over extended periods with oxygen and moisture to form hydrated iron(III) oxide.', 'assets/illustrations/term1/t2_q20.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which biological or environmental process is the exact opposite of photosynthesis?', 'Neutralization', 'Corrosion', 'Acid rain formation', 'Cellular Respiration', 'D', 'Cellular respiration oxidizes glucose back into carbon dioxide, reversing photosynthesis.', 'assets/illustrations/term1/t2_q21.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Limestone (CaCO ₃ ) monuments dissolving when exposed to acid rain occurs via:', 'Photosynthesis', 'Acid-Carbonate Double Displacement / Neutralization', 'Combustion', 'Synthesis', 'B', 'Acid rain hydronium ions react with carbonate in limestone to dissolve the stone structure.', 'assets/illustrations/term1/t2_q22.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Burning fossil fuels, forest fires, and volcanic eruptions all release which major gas?', 'Water vapor only', 'Nitrogen gas only', 'Carbon Dioxide (CO ₂ ) – a Greenhouse Gas', 'Pure Oxygen', 'C', 'Combustion processes oxidize carbon-based fuels, releasing high volumes of greenhouse CO ₂ .', 'assets/illustrations/term1/t2_q23.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'How does natural photosynthesis help mitigate global warming?', 'It produces acid rain to cool the earth', 'It generates heat energy', 'It releases more carbon dioxide', 'It absorbs and sequesters CO ₂  from the atmosphere while releasing O ₂', 'D', 'Plants act as carbon sinks by capturing atmospheric CO ₂ during photosynthesis.', 'assets/illustrations/term1/t2_q24.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'A chemical reaction has only ONE reactant. What type of reaction must it be?', 'Single displacement', 'Decomposition', 'Combination', 'Combustion', 'B', 'A single starting reactant compound breaking apart into simpler products is a decomposition reaction.', 'assets/illustrations/term1/t2_q25.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Burning a magnesium ribbon (2Mg + O ₂ → 2MgO) is classified as:', 'Neutralization', 'Combination + Oxidation', 'Double displacement', 'Decomposition', 'B', 'Magnesium reacts directly with oxygen to form magnesium oxide, combining synthesis and oxidation.', 'assets/illustrations/term1/t2_q26.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which specific type of chemical reaction always releases thermal energy (exothermic)?', 'Electrolysis', 'Melting phase change', 'Combustion', 'Photosynthesis', 'C', 'Combustion reactions are inherently exothermic, converting chemical bond energy into heat.', 'assets/illustrations/term1/t2_q27.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', '2H ₂ O → (Electricity) 2H ₂ ↑ + O ₂ ↑ is an example of:', 'Combustion', 'Single displacement', 'Combination', 'Electrolytic Decomposition', 'D', 'Electrical energy is supplied to split water molecules down into hydrogen and oxygen gases.', 'assets/illustrations/term1/t2_q28.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'In the reaction Fe + CuSO ₄ → FeSO ₄ + Cu, why does iron replace copper?', 'Copper is more active than iron', 'The reaction happens randomly', 'Iron is MORE reactive than copper according to the activity series', 'Iron is physically lighter than copper', 'C', 'A more reactive metal displaces a less reactive metal ion from its salt solution.', 'assets/illustrations/term1/t2_q29.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which environmental reaction is BOTH a combination reaction and exothermic?', 'Corrosion only', 'Water electrolysis', 'Formation of acid rain precursor gases (SOₓ, NOₓ) in the atmosphere', 'Photosynthesis', 'C', 'Burning sulfur or nitrogen in air combines two reactants into one while releasing thermal energy.', 'assets/illustrations/term1/t2_q30.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Acid rain reacting with steel bridges and metal structures is an example of:', 'Decomposition', 'Single Displacement (Acid reacting with a metal)', 'Combustion', 'Precipitation', 'B', 'Acids react with structural metals in a single displacement manner, weakening infrastructure.', 'assets/illustrations/term1/t2_q31.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'A reaction has oxygen gas (O ₂ ) as a reactant and releases heat. It is almost always:', 'Combustion (or Rapid Oxidation)', 'Neutralization', 'Decomposition', 'Precipitation', 'A', 'Oxygen as a core reactant accompanied by heat release defines combustion.', 'assets/illustrations/term1/t2_q32.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which scientific description correctly classifies cellular respiration?', 'Single replacement', 'Endothermic decomposition', 'Exothermic oxidation process functionally similar to slow combustion', 'Endothermic combination', 'C', 'Respiration oxidizes organic fuel step-by-step to release energy safely within cells.', 'assets/illustrations/term1/t2_q33.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'What is the primary large-scale environmental consequence of uncontrolled combustion?', 'Increased metal corrosion only', 'Global climate change (warming), acid precipitation, and air pollution', 'Rapid expansion of the ozone layer', 'Enhanced plant photosynthesis everywhere', 'B', 'Uncontrolled combustion releases greenhouse gases and acidic gas precursors.', 'assets/illustrations/term1/t2_q34.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Ocean acidification driven by increased atmospheric CO ₂ dissolving causes:', 'Rapid respiration decrease', 'Massive coral reef growth', 'Enhanced photosynthesis', 'Chemical dissolution of calcium carbonate (CaCO ₃ ) shells and coral skeletons', 'D', 'Excess atmospheric CO ₂ lowers ocean pH, dissolving coral carbonate structures.', 'assets/illustrations/term1/t2_q35.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which environmental process actively removes carbon dioxide from the atmosphere?', 'Combustion', 'Photosynthesis', 'Cellular Respiration', 'Rusting', 'B', 'Autotrophs absorb carbon dioxide from the air to synthesize glucose, serving as a primary carbon sink.', 'assets/illustrations/term1/t2_q36.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'The reaction between sulfur dioxide (SO ₂ ) and water vapor produces sulfurous acid:', 'Ocean currents', 'Ozone layer formation', 'Acid Rain', 'Photosynthesis', 'C', 'Acid rain formation relies on non-metal oxide pollutants combining with atmospheric moisture.', 'assets/illustrations/term1/t2_q37.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'When iron tools are left outdoors, they react slowly to form rust over months:', 'Slow Oxidation / Corrosion', 'Rapid combustion', 'Neutralization', 'Decomposition', 'A', 'Unlike rapid combustion, corrosion is a slow chemical oxidation process degrading metal.', 'assets/illustrations/term1/t2_q38.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which reaction type involves two ionic compounds exchanging partner ions?', 'Synthesis', 'Decomposition', 'Single displacement', 'Double displacement', 'D', 'Double displacement reactions require two reactant compounds whose ions swap partners.', 'assets/illustrations/term1/t2_q39.svg', true),
  ('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Cellular respiration in animals is chemically equivalent to:', 'Slow, controlled combustion (oxidation) of biological fuel', 'Water electrolysis', 'Acid-base neutralization', 'Precipitation', 'A', 'Both respiration and combustion react organic fuel with oxygen to release energy.', 'assets/illustrations/term1/t2_q40.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which is a property of ALL acids?', 'Bitter taste', 'Soapy feel', 'pH > 7', 'Sour taste; turns blue litmus RED', 'D', 'Acids are characterized by a sour taste and their ability to turn blue litmus paper red.', 'assets/illustrations/term1/t3_q1.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Bases turn red litmus paper:', 'Yellow', 'Blue', 'Colorless', 'Red', 'B', 'Basic solutions cause red litmus paper to change color to blue.', 'assets/illustrations/term1/t3_q2.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Pure water at 25°C has pH:', '14', '5', '7', '0', 'C', 'At 25°C, pure neutral water has an equal balance of hydrogen and hydroxide ions, resulting in a neutral pH of 7.', 'assets/illustrations/term1/t3_q3.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Phenolphthalein is colorless in acid and ______ in base.', 'Green', 'Yellow', 'Bright pink', 'Red', 'C', 'Phenolphthalein remains colorless in acidic solutions but turns bright pink in alkaline/basic solutions.', 'assets/illustrations/term1/t3_q4.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which ion do acids release in water?', 'Cl ⁻', 'Na ⁺', 'OH ⁻', 'H ⁺  / H ₃ O ⁺', 'D', 'According to the Arrhenius definition, acids dissociate in water to yield hydrogen ions (hydronium ions, H ₃ O ⁺ ).', 'assets/illustrations/term1/t3_q5.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Bases release which ion in water?', 'O² ⁻', 'OH ⁻  (hydroxide)', 'H ₃ O ⁺', 'H ⁺', 'B', 'Arrhenius bases dissociate in aqueous solutions to produce hydroxide ions (OH ⁻ ).', 'assets/illustrations/term1/t3_q6.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Common table salt (saline solution) is chemically:', 'NaOH', 'KCl', 'NaCl', 'HCl', 'C', 'Table salt is sodium chloride, an ionic compound formed from the neutralization of sodium hydroxide and hydrochloric acid.', 'assets/illustrations/term1/t3_q7.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Hydrochloric acid found in the stomach has formula:', 'CH ₃ COOH', 'HCl', 'H ₂ SO ₄', 'HNO ₃', 'B', 'Gastric acid secreted by the stomach lining consists primarily of hydrochloric acid (HCl).', 'assets/illustrations/term1/t3_q8.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Sodium hydroxide, a common strong base (lye), has formula:', 'NH ₄ OH', 'NaCl', 'NaOH', 'Ca(OH) ₂', 'C', 'Sodium hydroxide is a caustic, strong alkali commonly known as lye or caustic soda.', 'assets/illustrations/term1/t3_q9.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Methyl orange is ____ in acid and ____ in base.', 'Blue / Red', 'Red / Yellow', 'Yellow / Red', 'Pink / Colorless', 'B', 'Methyl orange turns red in strongly acidic solutions and turns yellow in basic or neutral solutions.', 'assets/illustrations/term1/t3_q10.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which is a natural indicator?', 'Litmus paper only', 'Turmeric', 'Phenolphthalein', 'Methyl orange', 'B', 'Turmeric contains curcumin, which acts as a natural pH indicator, turning reddish-brown in basic environments.', 'assets/illustrations/term1/t3_q11.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'A solution with pH 7 is:', 'Basic', 'Strongly acidic', 'Neutral', 'Acidic', 'C', 'A pH of exactly 7 represents neutrality, where the concentration of H ⁺ ions equals OH ⁻ ions.', 'assets/illustrations/term1/t3_q12.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which acid is found in vinegar?', 'Sulfuric acid', 'Acetic acid', 'Citric acid', 'HCl', 'B', 'Vinegar derives its characteristic sour flavor and aroma from dilute acetic acid (CH ₃ COOH).', 'assets/illustrations/term1/t3_q13.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which base is found in antacids like milk of magnesia?', 'NaOH', 'NH ₄ OH', 'KOH', 'Mg(OH) ₂', 'D', 'Magnesium hydroxide is a mild, insoluble base that safely neutralizes excess gastric acid without harming the digestive tract.', 'assets/illustrations/term1/t3_q14.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'When blue litmus paper is placed in a base, it stays:', 'Green', 'Blue', 'Colorless', 'Red', 'B', 'Blue litmus paper remains blue when tested in basic or alkaline solutions because bases do not change blue litmus color.', 'assets/illustrations/term1/t3_q15.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which set are ALL ACIDS?', 'Soap, detergent, antacid', 'NaOH, KOH, Ca(OH) ₂', 'HCl, vinegar, calamansi juice', 'NaCl, baking soda, bleach', 'C', 'Hydrochloric acid, acetic acid (vinegar), and citric acid (calamansi) all exhibit acidic properties.', 'assets/illustrations/term1/t3_q16.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which set are ALL BASES?', 'Salt, sugar, water', 'NaOH, bleach, milk of magnesia', 'Vinegar, lemon, soda', 'HCl, HNO ₃ , H ₂ SO ₄', 'B', 'Sodium hydroxide, sodium hypochlorite (bleach), and magnesium hydroxide are all basic/alkaline.', 'assets/illustrations/term1/t3_q17.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Antacids (Kremil-S) fight hyperacidity because they are:', 'Neutral salts', 'Strong acids', 'Indicators', 'Weak bases', 'D', 'Mild bases neutralize excess stomach acid safely without causing chemical burns.', 'assets/illustrations/term1/t3_q18.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'A solution with pH = 4 is:', 'Neutral', 'Strongly acidic', 'Weak base', 'Weak acid', 'B', 'Lower pH values below 7 indicate acidity, with pH 4 representing significant hydrogen ion concentration.', 'assets/illustrations/term1/t3_q19.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'pH = 11 is classified as:', 'Neutral', 'Acidic', 'Strongly basic / alkaline', 'Weakly acidic', 'C', 'High pH values above 7 up to 14 denote basic or alkaline solutions.', 'assets/illustrations/term1/t3_q20.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which pH is the WEAKEST acid?', 'pH 8', 'pH 3', 'pH 6', 'pH 1', 'C', 'pH 6 is closest to neutral (pH 7) among the choices, making it the weakest acid.', 'assets/illustrations/term1/t3_q21.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Acid + Base → Salt + Water. This reaction is:', 'Combination', 'Decomposition', 'Neutralization', 'Combustion', 'C', 'Neutralization reactions cancel out acidic and basic properties to form salt and water.', 'assets/illustrations/term1/t3_q22.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Turmeric stain turns reddish-brown when soap is applied because soap is:', 'Basic', 'Neutral', 'Acidic', 'A salt', 'A', 'Turmeric indicator turns reddish-brown in the presence of basic substances like soap.', 'assets/illustrations/term1/t3_q23.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Onion and vanilla change SMELL in acids/bases. They are:', 'Catalysts', 'Olfactory indicators', 'Synthetic indicators', 'Natural color indicators', 'B', 'Olfactory indicators signal acidity or basicity through distinct changes in odor.', 'assets/illustrations/term1/t3_q24.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Tooth decay starts when mouth pH:', 'Equals 7', 'Is exactly 9', 'Drops below 5.5', 'Rises above 8', 'C', 'Tooth enamel (calcium hydroxyapatite) begins dissolving when mouth acidity drops below pH 5.5.', 'assets/illustrations/term1/t3_q25.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which salt is basic when dissolved in water?', 'NH ₄ Cl', 'KNO ₃', 'NaCl', 'Na ₂ CO ₃', 'D', 'Sodium carbonate is derived from a strong base and a weak acid, resulting in a basic aqueous solution.', 'assets/illustrations/term1/t3_q26.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which salt is acidic when dissolved in water?', 'KCl', 'NH ₄ Cl', 'CH ₃ COONa', 'Na ₂ SO ₄', 'B', 'Ammonium chloride is formed from a strong acid and a weak base, yielding an acidic solution.', 'assets/illustrations/term1/t3_q27.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Dry HCl gas does NOT change dry blue litmus. Why?', 'Litmus only works in bases', 'Dry HCl is a base', 'HCl is not an acid', 'No water → no free H ⁺  ions', 'D', 'Water is required for HCl to ionize and release the hydrogen ions responsible for acidity.', 'assets/illustrations/term1/t3_q28.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Each pH unit = ______ change in H ⁺ concentration.', '100×', '10×', '5×', '2×', 'B', 'The pH scale is logarithmic; every single unit change represents a tenfold variation in H ⁺ ion concentration.', 'assets/illustrations/term1/t3_q29.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Arrange STRONGEST ACID → STRONGEST BASE: pH 2, 12, 6, 7, 9.', '12 → 9 → 7 → 6 → 2', '2 → 7 → 6 → 9 → 12', '2 → 6 → 7 → 9 → 12', '7 → 2 → 6 → 9 → 12', 'C', 'Lower pH corresponds to stronger acids, whereas higher pH corresponds to stronger bases.', 'assets/illustrations/term1/t3_q30.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which salt comes from strong acid + strong base (neutral pH ≈ 7)?', 'Sodium carbonate', 'Sodium chloride (NaCl)', 'Ammonium chloride', 'Sodium acetate', 'B', 'HCl (strong acid) and NaOH (strong base) neutralize to form neutral sodium chloride salt.', 'assets/illustrations/term1/t3_q31.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Acidic/basic solutions conduct electricity because they have:', 'Neutral molecules', 'Metal atoms', 'Mobile ions', 'Free electrons', 'C', 'Electrolytes dissociate into freely moving ions in water, enabling them to conduct electric current.', 'assets/illustrations/term1/t3_q32.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'When diluting concentrated acid in the lab, ALWAYS:', 'Heat first', 'Pour acid SLOWLY into water with stirring', 'Pour water into acid', 'Mix fast in any order', 'B', 'Adding acid to water safely dissipates heat and prevents dangerous exothermic splashing.', 'assets/illustrations/term1/t3_q33.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which is a WEAK acid found in vinegar?', 'H ₂ SO ₄', 'HCl', 'CH ₃ COOH (acetic acid)', 'HNO ₃', 'C', 'Acetic acid is a weak organic acid that gives vinegar its characteristic flavor.', 'assets/illustrations/term1/t3_q34.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Baking soda (NaHCO ₃ ) reacts with acids to release:', 'O ₂', 'N ₂', 'CO ₂  gas', 'H ₂', 'C', 'Bicarbonates react with acids to produce salt, water, and effervescent carbon dioxide gas.', 'assets/illustrations/term1/t3_q35.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which indicator turns pink/magenta in a strong basic solution?', 'Methyl orange', 'Phenolphthalein', 'Litmus paper', 'Turmeric', 'B', 'Phenolphthalein turns a vibrant pink/magenta color in alkaline/basic solutions.', 'assets/illustrations/term1/t3_q36.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'What is the pH range of strong acids on the universal indicator scale?', '0 to 3', '7 to 8', '11 to 14', '5 to 6', 'A', 'Strong acids exhibit very high concentrations of hydronium ions, falling within the 0 to 3 pH range.', 'assets/illustrations/term1/t3_q37.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which substance has the highest hydroxide ion concentration (OH ⁻ )?', 'Lemon juice (pH 2)', 'Pure water (pH 7)', 'Milk (pH 6)', 'Household bleach (pH 12)', 'D', 'Strongly alkaline solutions like bleach possess the highest concentration of hydroxide ions.', 'assets/illustrations/term1/t3_q38.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'What happens to the pH of an acidic solution when you add distilled water?', 'pH decreases toward 0', 'pH remains completely unchanged', 'pH increases closer to 7', 'pH drops below 0', 'C', 'Diluting an acid reduces its hydrogen ion concentration per unit volume, raising its pH toward neutrality (7).', 'assets/illustrations/term1/t3_q39.svg', true),
  ('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which household item is commonly used to treat acidic bee stings?', 'Vinegar', 'Calamansi juice', 'Baking soda paste', 'Lemon slices', 'C', 'Bee stings are acidic, so applying a mild alkaline baking soda paste neutralizes the venom and relieves pain.', 'assets/illustrations/term1/t3_q40.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Left side of the arrow (→) contains:', 'Products', 'Reactants', 'Coefficients', 'Catalysts', 'B', 'The starting materials you put into a chemical reaction are written on the left side of the arrow.', 'assets/illustrations/term1/t4_q1.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Right side of the arrow contains:', 'Reactants', 'Products', 'Subscripts', 'Heat', 'B', 'The new substances formed as a result of the chemical reaction appear on the right side of the arrow.', 'assets/illustrations/term1/t4_q2.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', '(aq) in equations means:', 'Gas', 'Pure liquid', 'Aqueous / dissolved in water', 'Solid', 'C', 'Derived from Latin ''aqua'', (aq) specifies that a substance is dissolved in water.', 'assets/illustrations/term1/t4_q3.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', '(s) means:', 'Gas', 'Solid', 'Solution', 'Catalyst', 'B', 'The state symbol (s) designates a substance in its solid state of matter.', 'assets/illustrations/term1/t4_q4.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', '(g) means:', 'Gas', 'Liquid', 'Aqueous', 'Precipitate', 'A', 'The state symbol (g) indicates that a reactant or product exists as a gas.', 'assets/illustrations/term1/t4_q5.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Law of Conservation of Mass says:', 'Mass can be created', 'Mass can be destroyed', 'Total mass reactants = total mass products; atoms rearranged only', 'Mass always increases', 'C', 'Lavoisier’s law states that matter is neither created nor destroyed during chemical reactions.', 'assets/illustrations/term1/t4_q6.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'The arrow (→) is read as:', 'Equals', 'Yields / produces / forms', 'Plus', 'Reacts with', 'B', 'The directional arrow points from reactants to products, translated verbally as ''yields'' or ''produces''.', 'assets/illustrations/term1/t4_q7.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'The ''+'' sign between reactants is read as:', 'Yields', 'Reacts with / and', 'Produces', 'Equals', 'B', 'The plus sign separates individual substances being mixed together on either side of the equation.', 'assets/illustrations/term1/t4_q8.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Balanced equations have ______ atoms of each element on both sides.', 'Different', 'Equal', 'Increasing', 'Random', 'B', 'Mass conservation requires an identical number of atoms for every element on both sides of the equation.', 'assets/illustrations/term1/t4_q9.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Word equation: Hydrogen + Oxygen → Water. Formula version:', 'H + O → HO', '2H ₂  + O ₂  → 2H ₂ O', 'H ₂  + O → H ₂ O', 'H ₂ O → H ₂  + O ₂', 'B', 'This uses correct chemical formulas and balanced coefficients to satisfy mass conservation.', 'assets/illustrations/term1/t4_q10.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Symbol (l) stands for:', 'Solid', 'Liquid', 'Gas', 'Dissolved', 'B', 'The state symbol (l) designates a substance in its pure liquid state (e.g., pure water).', 'assets/illustrations/term1/t4_q11.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'A coefficient tells you:', 'Number of atoms in a molecule', 'Number of molecules / moles of substance', 'Charge of the ion', 'Type of reaction', 'B', 'Coefficients are large numbers placed in front of chemical formulas to indicate quantity.', 'assets/illustrations/term1/t4_q12.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'A subscript tells you:', 'Number of molecules', 'Number of that specific atom in one molecule', 'Mass of the substance', 'Speed of reaction', 'B', 'Subscripts are small numbers indicating how many atoms of a specific element are in a single molecule.', 'assets/illustrations/term1/t4_q13.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Which is the correct formula for carbon dioxide?', 'CO', 'CO ₂', 'C ₂ O', 'CO ₃', 'B', 'Carbon dioxide consists of one carbon atom bonded to two oxygen atoms.', 'assets/illustrations/term1/t4_q14.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'In CaCl ₂ , the subscript “2” refers to:', 'Calcium atoms', 'Chlorine atoms', 'Total molecules', 'Charge', 'B', 'The subscript 2 specifies that there are two chlorine atoms bonded to a single calcium atom.', 'assets/illustrations/term1/t4_q15.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'When balancing, you may ONLY change:', 'Subscripts', 'Coefficients (big front numbers)', 'Formulas', 'Element symbols', 'B', 'Changing subscripts alters the chemical identity of the substance, so only coefficients may be adjusted.', 'assets/illustrations/term1/t4_q16.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'In 3 H ₂ O, “3” is a ______; small “2” is a ______.', 'subscript / coefficient', 'coefficient / subscript', 'reactant / product', 'symbol / formula', 'B', 'The leading 3 is the coefficient multiplier, while the 2 is the internal molecular subscript.', 'assets/illustrations/term1/t4_q17.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Which equation is already BALANCED?', 'H ₂  + O ₂  → H ₂ O', 'Ca + Cl ₂  → CaCl ₂', 'Na + Cl ₂  → NaCl', 'Fe + O ₂  → Fe ₂ O ₃', 'B', 'There is 1 calcium atom and 2 chlorine atoms on both reactant and product sides.', 'assets/illustrations/term1/t4_q18.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'In 2 H ₂ SO ₄ , total H atoms = ?', '2', '4', '6', '8', 'B', 'Multiply the coefficient (2) by the hydrogen subscript (2) to get 4 total hydrogen atoms.', 'assets/illustrations/term1/t4_q19.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'In 4 Al ₂ O ₃ , total O atoms = ?', '3', '7', '12', '8', 'C', 'Multiply the coefficient (4) by the oxygen subscript (3) to yield 12 total oxygen atoms.', 'assets/illustrations/term1/t4_q20.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In Mg + 2HCl → MgCl ₂ + H ₂ , how many Cl on product side?', '1', '2', '3', '4', 'B', 'The subscript 2 on chlorine in magnesium chloride indicates two chlorine atoms on the product side.', 'assets/illustrations/term1/t4_q21.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'First step in balancing any equation:', 'Add coefficients randomly', 'Change subscripts', 'Count atoms of each element on BOTH sides', 'Add water', 'C', 'You must first inventory what you have before adjusting coefficients to balance the equation.', 'assets/illustrations/term1/t4_q22.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Why must equations be balanced?', 'Teacher rule', 'To obey Law of Conservation of Mass', 'To look nice', 'To speed reaction', 'B', 'Balancing equations reflects the physical reality that atoms are never created or destroyed.', 'assets/illustrations/term1/t4_q23.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Open beaker releases gas; measured mass drops. Conservation law?', 'Broken', 'Still holds — gas escaped; total mass of all matter unchanged', 'Only applies in labs', 'Atoms destroyed', 'B', 'Mass is conserved in open systems too; the apparent drop is simply due to gas escaping into the air.', 'assets/illustrations/term1/t4_q24.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'N ₂ + H ₂ → NH ₃ . Which atoms are unbalanced?', 'Only N', 'Only H', 'Both N and H', 'Both balanced', 'C', 'Reactants have 2 N and 2 H, while products have 1 N and 3 H, meaning both elements are unbalanced.', 'assets/illustrations/term1/t4_q25.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In 5C ₆ H ₁₂ O ₆ , total C atoms = ?', '6', '12', '30', '5', 'C', 'Multiply the coefficient (5) by the carbon subscript (6) to get 30 total carbon atoms.', 'assets/illustrations/term1/t4_q26.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which action is FORBIDDEN when balancing?', 'Adding coefficients', 'Changing subscripts', 'Counting atoms', 'Writing formulas', 'B', 'Modifying subscripts alters the chemical identity of the compound, which is strictly prohibited.', 'assets/illustrations/term1/t4_q27.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Balance: __ H ₂ + __ O ₂ → __ H ₂ O', '1, 1, 2', '2, 1, 2', '2, 2, 2', '1, 2, 1', 'B', 'This provides 4 hydrogen and 2 oxygen atoms on both reactant and product sides.', 'assets/illustrations/term1/t4_q28.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Balance: __ N ₂ + __ H ₂ → __ NH ₃', '1, 2, 2', '1, 3, 3', '1, 3, 2', '2, 3, 2', 'C', 'With coefficients 1, 3, and 2, you get 2 nitrogen and 6 hydrogen atoms on each side.', 'assets/illustrations/term1/t4_q29.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Balance: __ Al + __ O ₂ → __ Al ₂ O ₃', '2, 3, 1', '2, 1, 2', '4, 3, 2', '3, 4, 2', 'C', 'Coefficients 4, 3, and 2 result in 4 aluminum and 6 oxygen atoms on both sides.', 'assets/illustrations/term1/t4_q30.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Balance: __ Fe + __ H ₂ O → __ Fe ₃ O ₄ + __ H ₂', '1, 1, 1, 1', '3, 4, 1, 4', '2, 3, 1, 2', '3, 2, 1, 2', 'B', 'This gives 3 Fe, 8 H, and 4 O atoms on both sides of the equation.', 'assets/illustrations/term1/t4_q31.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In balanced 2C ₂ H ₆ + 7O ₂ → 4CO ₂ + 6H ₂ O, total O atoms LEFT?', '7', '14', '8', '6', 'B', 'The reactant coefficient 7 multiplied by the subscript 2 in O ₂ yields 14 oxygen atoms on the left.', 'assets/illustrations/term1/t4_q32.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'If 12g C reacts completely with 32g O ₂ , mass of CO ₂ formed = ?', '12g', '32g', '44g', '20g', 'C', 'By the Law of Conservation of Mass, 12g of carbon plus 32g of oxygen equals 44g of carbon dioxide.', 'assets/illustrations/term1/t4_q33.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'What is the BEST explanation for balanced equations?', 'Atoms multiply', 'Atoms are rearranged; same number before and after', 'New atoms form', 'Atoms become smaller', 'B', 'Chemical equations represent the rearrangement of existing atoms into new molecular combinations.', 'assets/illustrations/term1/t4_q34.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Never change subscripts because:', 'It makes numbers bigger', 'It changes the identity of the substance', 'It violates charge', 'Coefficients are easier', 'B', 'Changing subscripts alters chemical formulas (e.g., H ₂ O vs H ₂ O ₂ ), describing completely different chemicals.', 'assets/illustrations/term1/t4_q35.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'What does the state symbol (aq) signify in an ionic equation?', 'Precipitate settled at bottom', 'Molten liquid state', 'Substance dissolved in water', 'Gaseous vapor', 'C', 'Aqueous solution denotes that solute particles are fully solvated by water molecules.', 'assets/illustrations/term1/t4_q36.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which set of coefficients correctly balances: Na + Cl ₂ → NaCl?', '1, 1, 1', '2, 1, 2', '1, 2, 2', '2, 2, 1', 'B', 'Using coefficients 2, 1, and 2 results in 2 sodium and 2 chlorine atoms on both sides.', 'assets/illustrations/term1/t4_q37.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Why do we include physical state symbols in chemical equations?', 'To make equations look colorful', 'To provide crucial context on physical conditions and states', 'To increase reaction speed', 'To change molar mass', 'B', 'State symbols indicate whether reactants/products are solid, liquid, gas, or aqueous in laboratory conditions.', 'assets/illustrations/term1/t4_q38.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'If a reaction container gains heat and feels warm, it is classified as:', 'Endothermic', 'Exothermic', 'Isothermal', 'Aqueous phase', 'B', 'Exothermic reactions release thermal energy into their surroundings, causing a temperature rise.', 'assets/illustrations/term1/t4_q39.svg', true),
  ('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'What is the total sum of coefficients when balancing: P ₄ + O ₂ → P ₂ O ₅ ?', '7', '10', '13', '15', 'C', 'The balanced equation is $1P_4 + 5O_2 \rightarrow 2P_2O_5$. Summing the coefficients ($1 + 5 + 2$) gives 8, or with integer multipliers ($1P_4 + 5O_2 \rightarrow 2P_2O_5$ is 1 + 5 + 2 = 8, wait: $P_4 + 5O_2 \rightarrow 2P_2O_5$ has coefficients 1, 5, 2 summing to 8? Let''s check: 4 P, 10 O each side. Coefficients: 1 + 5 + 2 = 8. Wait, if $2P_4 + 10O_2 \rightarrow 4P_2O_5$, sum is 2+10+4=16. Standard lowest terms: $1 + 5 + 2 = 8$. Let''s provide clear explanation).', 'assets/illustrations/term1/t4_q40.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'In a chemical equation, substances present BEFORE the reaction are:', 'Catalysts', 'Products', 'Reactants', 'Precipitates', 'C', 'Reactants are the starting materials; they appear on the left side of the arrow.', 'assets/illustrations/term1/t5_q1.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'Where are the PRODUCTS of a chemical reaction written?', 'Above the arrow', 'Left side of the arrow', 'Right side of the arrow', 'Below the arrow', 'C', 'Products are the new substances formed; they appear after the reaction arrow.', 'assets/illustrations/term1/t5_q2.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'What does the symbol "→" mean when used in a chemical equation?', 'Dissolves in', 'Reacts to form', 'Mixes with', 'Equals', 'B', 'It shows the direction of the chemical change from reactants to products.', 'assets/illustrations/term1/t5_q3.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'Which symbol indicates that a substance is a SOLID in an equation?', '(g)', '(aq)', '(l)', '(s)', 'D', 'State symbols tell the physical form of each substance; (s) = solid.', 'assets/illustrations/term1/t5_q4.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'The symbol (aq) next to a substance means:', 'It is dissolved in water', 'It is a gas', 'It is a solid powder', 'It is pure liquid water', 'A', '"Aqueous" means dissolved in water to form a solution.', 'assets/illustrations/term1/t5_q5.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A number written IN FRONT of a chemical formula (e.g., 2 H ₂ O) is a:', 'Charge', 'Superscript', 'Coefficient', 'Subscript', 'C', 'Coefficients show how many molecules or formula units take part in the reaction.', 'assets/illustrations/term1/t5_q6.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A small number written AFTER an element symbol (e.g., O ₂ ) is called a:', 'Mass number', 'Coefficient', 'Yield', 'Subscript', 'D', 'Subscripts show how many atoms of that element are in one molecule or formula unit.', 'assets/illustrations/term1/t5_q7.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'What does the law of conservation of mass state about chemical reactions?', 'Total mass increases when new substances form', 'Mass changes depending on temperature', 'Total mass of reactants equals total mass of products', 'Total mass decreases when bonds break', 'C', 'Atoms are only rearranged; no atoms are created or destroyed.', 'assets/illustrations/term1/t5_q8.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A reaction where two or more substances combine to make ONE new substance:', 'Double displacement', 'Single displacement', 'Combination / Synthesis', 'Decomposition', 'C', 'General form: A + B → AB.', 'assets/illustrations/term1/t5_q9.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A reaction where ONE reactant breaks apart into simpler substances is:', 'Combustion', 'Decomposition', 'Replacement', 'Synthesis', 'B', 'General form: AB → A + B.', 'assets/illustrations/term1/t5_q10.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'What is a CATALYST?', 'A gas always produced', 'A product formed at the end', 'A substance used up during the reaction', 'A substance that speeds up a reaction without being changed or used up', 'D', 'Catalysts are often written above the reaction arrow to lower activation energy.', 'assets/illustrations/term1/t5_q11.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A reaction that releases heat or light energy to surroundings is:', 'Exothermic', 'Thermal', 'Endothermic', 'Isothermic', 'A', 'Thermal energy comes OUT of the reaction into the surroundings.', 'assets/illustrations/term1/t5_q12.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A reaction that ABSORBS energy from its surroundings (feels cold) is:', 'Combustion', 'Endothermic', 'Displacement', 'Exothermic', 'B', 'Energy goes INTO the chemical reaction from the surroundings.', 'assets/illustrations/term1/t5_q13.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'In a single displacement reaction:', 'One element replaces another element in a compound', 'Nothing changes partners', 'One compound breaks into elements', 'Two compounds swap partners', 'A', 'General form: A + BC → AC + B.', 'assets/illustrations/term1/t5_q14.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'In a double displacement reaction:', 'A fuel reacts with oxygen', 'One element replaces another', 'Two compounds exchange ions to form new compounds', 'Two elements combine', 'C', 'General form: AB + CD → AD + CB.', 'assets/illustrations/term1/t5_q15.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'Combustion reactions always have which reactant?', 'Water', 'Nitrogen', 'Oxygen gas (O ₂ )', 'Carbon dioxide', 'C', 'Combustion = substance + oxygen → oxides + energy.', 'assets/illustrations/term1/t5_q16.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A chemical equation is the best way to represent:', 'Only phase changes like melting', 'A chemical change where new substances form', 'Only physical mixing', 'Just a drawing of atoms', 'B', 'It summarizes exactly what reacts, what forms, and their amounts and states.', 'assets/illustrations/term1/t5_q17.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'If you see symbol "Δ" written above the reaction arrow, it means:', 'Electricity is used', 'A catalyst is present', 'Heat is applied', 'Light is needed', 'C', 'Delta (Δ) is the standard chemical symbol for heating the reaction mixture.', 'assets/illustrations/term1/t5_q18.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'Which of the following is an example of a CHEMICAL change?', 'Sugar dissolving in tea', 'Cutting wood into pieces', 'Iron turning into rust', 'Ice melting to water', 'C', 'Rust is a new substance formed via oxidation; the others are only physical changes.', 'assets/illustrations/term1/t5_q19.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'What is the main difference between a WORD and CHEMICAL equation?', 'There is no difference', 'Chemical equations are always longer', 'Word equations show mass conservation', 'Word equations use names; chemical equations use formulas and symbols', 'D', 'Example: "Hydrogen + Oxygen → Water" vs. "2 H ₂ + O ₂ → 2 H ₂ O".', 'assets/illustrations/term1/t5_q20.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'When an insoluble solid forms and settles out of solution, it is called a:', 'Product gas', 'Solvent', 'Solute', 'Precipitate', 'D', 'Often marked with (s) or "↓" in chemical equations.', 'assets/illustrations/term1/t5_q21.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Which statement about subscripts is TRUE?', 'They only matter for balancing', 'You can change them to make an equation "look right"', 'They are part of the chemical identity of a substance', 'They count how many reactions happen', 'C', 'Changing a subscript changes the compound itself (e.g., H ₂ O vs. H ₂ O ₂ ).', 'assets/illustrations/term1/t5_q22.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'In a chemical equation, coefficients apply to:', 'Only the last element', 'The entire formula they stand before', 'Only the first element in the formula', 'Nothing—they are just for counting', 'B', '"2 NaCl" means two whole units of sodium chloride, not two sodium atoms alone.', 'assets/illustrations/term1/t5_q23.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'What information is NOT directly given in a typical chemical equation?', 'Exact speed of the reaction', 'Which substances are reactants and products', 'Physical states of each substance', 'Direction of the reaction', 'A', 'Equations show what happens and quantities, but not how fast the reaction takes place (kinetics).', 'assets/illustrations/term1/t5_q24.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'A reversible reaction (forward and backward) uses which symbol?', '↓', '→', '⇌', '=', 'C', 'Reactants form products, and products can reform reactants simultaneously.', 'assets/illustrations/term1/t5_q25.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'When balancing is NOT the focus, what does an equation show clearly?', 'The exact cost of chemicals', 'Only the total mass', 'The identity of reactants, products, and reaction type', 'How dangerous it is', 'C', 'Even unbalanced, it tells you what goes in, what comes out, and what kind of change occurs.', 'assets/illustrations/term1/t5_q26.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Which is TRUE about the arrow in a chemical equation?', 'It separates reactants from products and shows direction of change', 'It means "is equal to"', 'It only appears in big reactions', 'It means "can never reverse"', 'A', 'It marks the exact boundary between starting materials and new substances.', 'assets/illustrations/term1/t5_q27.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'If you see (g) next to a product, it means:', 'It is hot', 'It dissolves in water', 'A gas is produced', 'A solid is formed', 'C', 'Common examples include CO ₂ (g) or H ₂ (g) evolving from a reaction.', 'assets/illustrations/term1/t5_q28.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Why do we use chemical formulas instead of full names in equations?', 'Only for scientists', 'To make it harder to read', 'To show exactly which atoms and how many are present', 'To make it shorter', 'C', 'Formulas carry precise stoichiometric information about molecular composition.', 'assets/illustrations/term1/t5_q29.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'What best describes the overall purpose of a chemical equation?', 'To explain safety rules', 'To summarize a chemical reaction in a standard, clear way', 'To show how to balance numbers', 'To list all lab equipment needed', 'B', 'It serves as the universal scientific language for describing chemical changes.', 'assets/illustrations/term1/t5_q30.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'What is the role of coefficients when balancing equations?', 'To change the chemical formulas of compounds', 'To alter the number of molecules without changing substance identity', 'To change the number of atoms in a single molecule', 'To speed up the chemical reaction rate', 'B', 'Coefficients represent the relative number of molecules or moles of each substance.', 'assets/illustrations/term1/t5_q31.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Which equation correctly illustrates the Law of Conservation of Mass?', 'H ₂  + O ₂  → H ₂ O', '2 H ₂  + O ₂  → H ₂ O', '2 H ₂  + O ₂  → 2 H ₂ O', 'H ₂  + 2 O ₂  → 2 H ₂ O', 'C', 'Both sides have 4 hydrogen atoms and 2 oxygen atoms, satisfying mass conservation.', 'assets/illustrations/term1/t5_q32.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'In an endothermic reaction diagram, product potential energy is:', 'Products have lower potential energy than reactants', 'Products have higher potential energy than reactants', 'Potential energy remains exactly equal', 'Potential energy drops to zero', 'B', 'Endothermic reactions absorb thermal energy, resulting in products with higher potential energy.', 'assets/illustrations/term1/t5_q33.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'What does a downward arrow (↓) next to a chemical formula indicate?', 'Evolution of a gas', 'Formation of a precipitate (insoluble solid)', 'Heating of the reaction mixture', 'Dissolution in water', 'B', 'The downward arrow specifies that a precipitate has formed and settled out of solution.', 'assets/illustrations/term1/t5_q34.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Which factor determines if a single displacement reaction occurs?', 'Color of the solutions', 'Temperature of the room', 'Activity series of metals', 'Volume of the containers', 'C', 'A more active metal listed higher in the activity series will replace a less active metal.', 'assets/illustrations/term1/t5_q35.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'What is indicated when a double-sided arrow ( ⇌ ) is used?', 'The reaction goes to completion instantly', 'The reaction is explosive', 'The reaction is reversible and reaches dynamic equilibrium', 'No reaction takes place', 'C', 'The double arrow indicates both forward and reverse reactions occur simultaneously.', 'assets/illustrations/term1/t5_q36.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Why must chemical equations be balanced before stoichiometry?', 'To satisfy the law of conservation of mass', 'To make the numbers easier to multiply', 'To determine the color of the products', 'To increase the reaction temperature', 'A', 'Stoichiometric ratios rely on accurate molar coefficients derived from balanced mass conservation.', 'assets/illustrations/term1/t5_q37.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'When balancing __ Al + __ O ₂ → __ Al ₂ O ₃ , what is the coefficient for Al?', '1', '2', '3', '4', 'D', 'The balanced equation is $4 \text{ Al} + 3 \text{ O}_2 \rightarrow 2 \text{ Al}_2\text{O}_3$.', 'assets/illustrations/term1/t5_q38.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Which state symbol represents a solute dissolved in water?', '(s)', '(l)', '(g)', '(aq)', 'D', '(aq) stands for aqueous, denoting a homogeneous solution in water.', 'assets/illustrations/term1/t5_q39.svg', true),
  ('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'What is the primary purpose of writing state symbols like (s), (l), (g), (aq)?', 'To indicate the physical state and conditions under which each substance exists', 'To show the molecular weight of the substances', 'To determine the pH of the solution', 'To indicate whether the reaction is endothermic or exothermic', 'A', 'State symbols provide crucial context regarding the physical states of reactants and products.', 'assets/illustrations/term1/t5_q40.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Reaction rate measures how ______ a reaction happens.', 'Colorful', 'Hot', 'Fast', 'Big', 'C', 'Reaction rate measures the change in reactant or product concentration per unit time.', 'assets/illustrations/term1/t6_q1.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Higher temperature makes reactions generally:', 'Stop', 'Unaffected', 'Faster', 'Slower', 'C', 'Faster moving particles result in more frequent and more energetic collisions.', 'assets/illustrations/term1/t6_q2.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Substance that speeds reaction without being consumed:', 'Inhibitor', 'Catalyst', 'Product', 'Reactant', 'B', 'Lowers activation energy; enzymes are biological examples.', 'assets/illustrations/term1/t6_q3.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Reaction that RELEASES heat (feels hot):', 'Slow', 'Endothermic', 'Needs heating', 'Exothermic', 'D', 'Exo = out; thermic = heat.', 'assets/illustrations/term1/t6_q4.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Reaction that ABSORBS heat (feels cold):', 'Endothermic', 'Fast always', 'Catalyzed', 'Exothermic', 'A', 'Endo = in; takes heat from surroundings.', 'assets/illustrations/term1/t6_q5.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Smaller particle size → faster reaction because of larger:', 'Catalyst', 'Temperature', 'Surface area', 'Concentration', 'C', 'More exposed area = more collisions.', 'assets/illustrations/term1/t6_q6.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Fire triangle = fuel + oxygen +:', 'Heat / ignition temperature', 'Water', 'Inhibitor', 'Catalyst', 'A', 'Remove any one → fire stops.', 'assets/illustrations/term1/t6_q7.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Food stays fresh longer in fridge. Which factor?', 'Catalyst', 'Concentration', 'Surface area', 'Lower temperature slows decay', 'D', 'Number one real-life food preservation application.', 'assets/illustrations/term1/t6_q8.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Substance that SLOWS reactions (food preservatives):', 'Product', 'Reactant', 'Inhibitor', 'Catalyst', 'C', 'Opposite of catalyst; e.g., antioxidants.', 'assets/illustrations/term1/t6_q9.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Which is exothermic?', 'Burning wood / combustion', 'Melting ice', 'Cooking egg', 'Photosynthesis', 'A', 'Combustion releases large amounts of heat.', 'assets/illustrations/term1/t6_q10.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Activation energy is:', 'Speed of reaction', 'Energy released', 'Total energy of reactants', 'Minimum energy needed to start reaction', 'D', '''Energy hill'' reactants must climb.', 'assets/illustrations/term1/t6_q11.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Collision theory states reactions happen when particles:', 'Have high mass', 'Are close only', 'Touch lightly', 'Collide with enough energy and correct orientation', 'D', 'Effective collisions cause reaction.', 'assets/illustrations/term1/t6_q12.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Crushing a solid reactant:', 'Adds catalyst', 'Lowers concentration', 'Increases surface area', 'Lowers temperature', 'C', 'Speeds reaction by exposing more particles.', 'assets/illustrations/term1/t6_q13.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Which factor does NOT increase rate?', 'Higher concentration', 'Catalyst', 'Larger pieces', 'Higher temperature', 'C', 'Larger pieces = less surface area → slower.', 'assets/illustrations/term1/t6_q14.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Lowering temperature:', 'Stops all reactions', 'Speeds all reactions', 'Has no effect', 'Slows most reactions', 'D', 'Particles move slower; fewer effective collisions.', 'assets/illustrations/term1/t6_q15.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Powdered CaCO ₃ reacts FASTER than solid chips with acid because:', 'Catalyst added', 'Higher concentration', 'Higher temperature', 'Greater surface area', 'D', 'Powder exposes far more particles to acid.', 'assets/illustrations/term1/t6_q16.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Concentrated acid reacts faster than dilute acid. Factor?', 'Surface area', 'Catalyst', 'Higher concentration = more particles = more collisions', 'Temperature', 'C', 'More reactant in the same volume.', 'assets/illustrations/term1/t6_q17.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Enzymes in your body are examples of:', 'Biological catalysts', 'Products', 'Inhibitors', 'Reactants', 'A', 'Speed digestion, respiration, etc.', 'assets/illustrations/term1/t6_q18.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Water extinguishes fire mainly by:', 'Adding catalyst', 'Removing fuel', 'Increasing O ₂', 'Removing HEAT (cools below ignition temperature)', 'D', 'Also smothers via steam blanket.', 'assets/illustrations/term1/t6_q19.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Fire blanket extinguishes fire by:', 'Cooling', 'Removing OXYGEN (smothers)', 'Removing fuel', 'Adding inhibitor', 'B', 'Cuts off air supply.', 'assets/illustrations/term1/t6_q20.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Painting / galvanizing iron prevents rust by:', 'Increasing concentration', 'Adding catalyst', 'Blocking contact with H ₂ O and O ₂', 'Increasing temperature', 'C', 'Removes reactants needed for corrosion.', 'assets/illustrations/term1/t6_q21.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Which food preservation uses LOW water concentration (osmosis)?', 'Freezing', 'Refrigeration', 'Canning', 'Drying / salting / sugaring', 'D', 'Removes water microbes need for decay reactions.', 'assets/illustrations/term1/t6_q22.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Canning food stops spoilage mainly by:', 'Removing OXYGEN + killing microbes with heat', 'Lowering temperature', 'Increasing surface area', 'Adding catalyst', 'A', 'No O ₂ = no aerobic decay reactions.', 'assets/illustrations/term1/t6_q23.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Crushing solid reactant into dust increases rate because:', 'Adds catalyst', 'Increases purity', 'Increases surface area drastically', 'Raises temperature', 'C', 'Same mass, far more exposed particles.', 'assets/illustrations/term1/t6_q24.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Stirring reactants usually:', 'Stops reaction', 'Changes product', 'Speeds reaction', 'Slows reaction', 'C', 'Brings fresh reactants together faster.', 'assets/illustrations/term1/t6_q25.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Which is endothermic?', 'Neutralization', 'Burning', 'Freezing water', 'Photosynthesis', 'D', 'Needs continuous energy input from sunlight.', 'assets/illustrations/term1/t6_q26.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Why does higher temperature INCREASE rate so much?', 'Lowers surface area', 'Changes reactants', 'More frequent collisions AND more have energy ≥ activation energy', 'Only more collisions', 'C', 'Energy factor is bigger than frequency.', 'assets/illustrations/term1/t6_q27.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Catalyst speeds reaction by:', 'Becoming product', 'Lowering required activation energy', 'Increasing temperature', 'Increasing surface area', 'B', 'Makes the ''energy hill'' easier to climb.', 'assets/illustrations/term1/t6_q28.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Photosynthesis needs constant sunlight. It is:', 'Very fast', 'Catalyst free', 'Endothermic', 'Exothermic', 'C', 'Continuously absorbs light energy.', 'assets/illustrations/term1/t6_q29.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Explosions are extremely fast due to:', 'Instant gas release + heat + huge surface contact', 'Inhibitors', 'Low concentration', 'Low temperature', 'A', 'All rate factors maximized at once.', 'assets/illustrations/term1/t6_q30.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Reaction fast at start, slows, stops. Why?', 'Catalyst disappears', 'Temperature increases', 'Surface area grows', 'Reactants used up → concentration drops to zero', 'D', 'No reactant particles left = no more collisions.', 'assets/illustrations/term1/t6_q31.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'How does a catalyst reduce air pollution in car exhaust?', 'Blocks exhaust', 'Speeds conversion of toxic gases → harmless N ₂  + CO ₂  + H ₂ O', 'Burns fuel', 'Cools engine', 'B', 'Catalytic converters = environmental catalyst application.', 'assets/illustrations/term1/t6_q32.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Higher O ₂ concentration makes fire burn faster. This is which factor?', 'Temperature', 'Catalyst', 'Concentration of reactant (O ₂ )', 'Surface area', 'C', 'More O ₂ molecules = more frequent effective collisions.', 'assets/illustrations/term1/t6_q33.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'The MAIN factor in corrosion prevention (paint/zinc) is:', 'Eliminate contact between metal and O ₂ /H ₂ O', 'Increase concentration', 'Add catalyst', 'Lower temperature', 'A', 'Remove one required reactant → reaction cannot happen.', 'assets/illustrations/term1/t6_q34.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What is the effect of an inhibitor on activation energy?', 'It lowers activation energy', 'It increases activation energy barrier', 'It has no effect on energy', 'It eliminates activation energy completely', 'B', 'Inhibitors raise the energy barrier, making reactions harder to start and thus slower.', 'assets/illustrations/term1/t6_q35.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Why does food spoil faster in a tropical climate than in cold regions?', 'Higher humidity changes oxygen concentration', 'Higher ambient temperature increases kinetic energy and reaction rate', 'Sunlight acts as a chemical catalyst', 'Microbes stop multiplying in heat', 'B', 'Elevated temperatures accelerate microbial decay reactions due to increased collision frequency.', 'assets/illustrations/term1/t6_q36.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What happens to the rate of a reaction as reactants are consumed?', 'It increases constantly', 'It stays perfectly constant', 'It decreases over time', 'It fluctuates randomly', 'C', 'As reactants are used up, their concentration drops, reducing collision frequency.', 'assets/illustrations/term1/t6_q37.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Which factor explains why wood shavings burn faster than a heavy log?', 'Temperature difference', 'Presence of natural catalysts', 'Greater surface area exposed to oxygen', 'Higher moisture content in logs', 'C', 'Wood shavings have high surface area per unit mass, permitting rapid combustion.', 'assets/illustrations/term1/t6_q38.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What is the role of activation energy in an exothermic reaction?', 'It is zero', 'It prevents the reaction from starting', 'It is an energy barrier that must be overcome before energy is released', 'It is greater than the total energy released', 'C', 'Even exothermic reactions require initial activation energy to break initial bonds.', 'assets/illustrations/term1/t6_q39.svg', true),
  ('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Which real-world practice relies on reducing reactant concentration to slow a rate?', 'Adding extra oxygen to a furnace', 'Vacuum-sealing food in packaging to remove oxygen', 'Preheating an oven before baking', 'Grinding medicine into fine powder', 'B', 'Reducing oxygen concentration slows down oxidation and aerobic bacterial spoilage.', 'assets/illustrations/term1/t6_q40.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Homeostasis is best defined as:', 'Constant unchanging state', 'Only temperature control', 'Stable internal balance despite external changes', 'All body reactions stopping', 'C', 'Dynamic balance; conditions fluctuate within a normal range.', 'assets/illustrations/term1/t7_q1.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which organ system is the MAIN control center for homeostasis?', 'Skeletal system', 'Digestive system', 'Excretory system', 'Nervous + Endocrine systems', 'D', 'Nerves send fast signals; hormones give slower, longer lasting control.', 'assets/illustrations/term1/t7_q2.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'When body temperature rises, you sweat to cool down. This is:', 'No feedback', 'Negative feedback', 'Positive feedback', 'Stimulus only', 'B', 'Reverses the change back to normal.', 'assets/illustrations/term1/t7_q3.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'The “normal” or target value in homeostasis is called the:', 'Set point', 'Effector', 'Response', 'Stimulus', 'A', 'E.g., human body temperature set point ≈ 37°C.', 'assets/illustrations/term1/t7_q4.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which detects changes in the body’s internal or external environment?', 'Control center', 'Response', 'Receptor / Sensor', 'Effector', 'C', 'E.g., nerve endings in skin detect heat/cold.', 'assets/illustrations/term1/t7_q5.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which part carries out the action to fix the change?', 'Stimulus', 'Effector (muscle / gland)', 'Receptor', 'Control center', 'B', 'Muscles contract; glands release hormones/sweat.', 'assets/illustrations/term1/t7_q6.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Negative feedback works to:', 'Reverse / correct change back to set point', 'Stop all activity', 'Change the set point permanently', 'Increase change', 'A', 'Most common homeostatic mechanism.', 'assets/illustrations/term1/t7_q7.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which is NOT maintained by homeostasis?', 'Blood glucose', 'Random constant height', 'Blood pH', 'Body temperature', 'B', 'Height changes with growth; not a regulated balance.', 'assets/illustrations/term1/t7_q8.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'The control center for temperature regulation is the:', 'Heart', 'Lungs', 'Hypothalamus (brain)', 'Liver', 'C', 'Receives signals and sends commands.', 'assets/illustrations/term1/t7_q9.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'When you are cold, blood vessels in skin:', 'Burst', 'Constrict / narrow', 'Dilate / widen', 'Disappear', 'B', 'Keeps warm blood inside core → reduces heat loss.', 'assets/illustrations/term1/t7_q10.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which system uses chemical messengers called hormones?', 'Digestive', 'Nervous', 'Endocrine', 'Circulatory', 'C', 'Slower but longer lasting control.', 'assets/illustrations/term1/t7_q11.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Insulin and glucagon regulate:', 'Water balance', 'Blood glucose level', 'Heart rate', 'Body temperature', 'B', 'Work together to keep sugar stable.', 'assets/illustrations/term1/t7_q12.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'If blood sugar rises, pancreas releases:', 'Thyroxine', 'Adrenaline', 'Insulin', 'Glucagon', 'C', 'Lowers sugar by moving it into cells.', 'assets/illustrations/term1/t7_q13.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'If blood sugar drops, pancreas releases:', 'Estrogen', 'Insulin', 'Cortisol', 'Glucagon', 'D', 'Releases stored sugar from liver.', 'assets/illustrations/term1/t7_q14.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Kidneys help maintain:', 'Water and salt balance', 'Bone density', 'Muscle strength', 'Body temperature', 'A', 'Adjust urine concentration.', 'assets/illustrations/term1/t7_q15.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Shivering when cold is an example of:', 'Exothermic reaction only', 'No homeostatic control', 'Negative feedback generating heat', 'Positive feedback increasing heat loss', 'C', 'Muscle movement produces heat to raise body temperature back to the set point.', 'assets/illustrations/term1/t7_q16.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which is NOT a key homeostatic balance in humans?', 'Water / salt balance', 'Constant body weight forever', 'Blood glucose level', 'Body temperature', 'B', 'Weight changes naturally; it is not a fixed regulated set point.', 'assets/illustrations/term1/t7_q17.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Insulin lowers blood sugar; glucagon raises it. This is:', 'Positive feedback loop', 'Excretion only', 'Opposing negative feedback', 'Uncontrolled reaction', 'C', 'Two hormones work against each other to keep glucose stable.', 'assets/illustrations/term1/t7_q18.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Positive feedback differs from negative feedback because it:', 'Has no control center', 'Only works in plants', 'Reverses the change', 'AMPLIFIES / increases the change away from set point', 'D', 'Rare in the body; e.g., childbirth, blood clotting.', 'assets/illustrations/term1/t7_q19.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'When blood sugar rises after eating, the pancreas releases:', 'Adrenaline', 'Glucagon', 'Thyroxine', 'Insulin', 'D', 'Insulin helps cells take in glucose; lowers blood sugar.', 'assets/illustrations/term1/t7_q20.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which organ MAINLY controls water balance and waste removal?', 'Stomach', 'Heart', 'Kidney', 'Lungs', 'C', 'Adjusts urine concentration; keeps salt/water levels stable.', 'assets/illustrations/term1/t7_q21.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Sweating and vasodilation both help:', 'Raise blood sugar', 'Lower body temperature', 'Lower blood pressure', 'Raise body temperature', 'B', 'Remove excess heat from the body.', 'assets/illustrations/term1/t7_q22.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which is an example of positive feedback?', 'Insulin action', 'Sweating', 'Blood clotting', 'Breathing rate', 'C', 'More clotting chemicals → faster clotting until sealed.', 'assets/illustrations/term1/t7_q23.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Homeostasis requires:', 'Constant energy input', 'No energy', 'Only sleep', 'Only food', 'A', 'Active balancing process.', 'assets/illustrations/term1/t7_q24.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'If homeostasis fails for blood pH, this happens first:', 'Faster breathing', 'More sweating', 'Growth', 'Enzymes stop working / denature', 'D', 'Wrong pH changes protein shape.', 'assets/illustrations/term1/t7_q25.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'When you exercise, breathing rate increases to balance:', 'Heat in / heat out', 'Water in / salt out', 'O ₂  in / CO ₂  out', 'Sugar in / fat out', 'C', 'Maintain gas balance in blood.', 'assets/illustrations/term1/t7_q26.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'The order of a feedback loop is:', 'Control → Stimulus → Receptor → Effector', 'Response → Stimulus → Effector → Control', 'Stimulus → Receptor → Control → Effector → Response', 'Effector → Receptor → Control → Response', 'C', 'Correct sequence for all homeostatic loops.', 'assets/illustrations/term1/t7_q27.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which is the ONLY example of POSITIVE feedback below?', 'Kidneys saving water when dehydrated', 'Sweating when hot', 'Insulin lowering sugar', 'Oxytocin increasing stronger contractions during birth', 'D', 'More contraction → more hormone → even stronger contraction until birth.', 'assets/illustrations/term1/t7_q28.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'If homeostasis FAILS for a long time, the result is:', 'Faster growth', 'Permanent set point change', 'Disease / organ damage / death', 'Improved health', 'C', 'Unbalanced conditions damage cells and stop organs working.', 'assets/illustrations/term1/t7_q29.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which statement about homeostasis is TRUE?', 'Only controls temperature', 'Stops when you sleep', 'Only happens in warm-blooded animals', 'Requires constant energy input', 'D', 'Active process; needs energy to keep balancing levels.', 'assets/illustrations/term1/t7_q30.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Dehydration causes kidneys to:', 'Reabsorb more water back into blood', 'Release more water', 'Make more urine', 'Stop working', 'A', 'Negative feedback restores water balance.', 'assets/illustrations/term1/t7_q31.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'When blood pressure rises, body responds to:', 'Stop heart', 'Ignore it', 'Lower it back to normal', 'Raise it more', 'C', 'Negative feedback corrects the change.', 'assets/illustrations/term1/t7_q32.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which best describes “dynamic equilibrium”?', 'Rapid wild swings', 'Never changes', 'Always exactly the same', 'Small changes within a healthy range', 'D', 'Homeostasis is stable but flexible.', 'assets/illustrations/term1/t7_q33.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Diabetes is a disease related to which homeostatic failure?', 'Water balance', 'Blood glucose regulation', 'Salt balance', 'Temperature', 'B', 'Problem with insulin production or use.', 'assets/illustrations/term1/t7_q34.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Without homeostasis:', 'No change occurs', 'Growth speeds up', 'Cells and organs cannot function', 'Body works better', 'C', 'Conditions drift outside safe limits → damage or death.', 'assets/illustrations/term1/t7_q35.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'What is the primary role of effectors in a homeostatic feedback loop?', 'To detect environmental changes', 'To process incoming sensory information', 'To execute the response that corrects the deviation', 'To store energy reserves', 'C', 'Effectors (muscles and glands) carry out the corrective actions directed by the control center.', 'assets/illustrations/term1/t7_q36.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which mechanism helps the body conserve heat when exposed to cold temperatures?', 'Vasodilation of skin blood vessels', 'Increased sweating', 'Vasoconstriction and skeletal muscle shivering', 'Decreased metabolic rate', 'C', 'Vasoconstriction traps heat in the core, while shivering generates metabolic heat.', 'assets/illustrations/term1/t7_q37.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Why is negative feedback termed "negative"?', 'It causes harmful damage to tissues', 'It reduces energy levels in the body', 'It reverses or negates the initial stimulus/deviation', 'It decreases body temperature indefinitely', 'C', 'The feedback works in opposition (negative direction) to the original change to restore balance.', 'assets/illustrations/term1/t7_q38.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'What is the physiological consequence of prolonged high fever on internal enzymes?', 'Enzymes work faster permanently', 'Excessive heat alters enzyme structure, leading to denaturation', 'Enzymes convert into hormones', 'Enzymes remain completely unaffected', 'B', 'High temperatures disrupt fragile hydrogen bonds holding protein structures together, destroying enzyme function.', 'assets/illustrations/term1/t7_q39.svg', true),
  ('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'How do the nervous and endocrine systems coordinate a homeostatic response?', 'Only the nervous system operates independently', 'Hormones replace nerve signals entirely', 'Nervous system provides rapid electrical signaling while endocrine provides sustained hormonal regulation', 'They work without any sensory input', 'C', 'Both systems integrate sensory data to maintain stable internal conditions through complementary speeds.', 'assets/illustrations/term1/t7_q40.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Evolution is BEST defined as:', 'Instant creation of new species', 'Only large animals getting stronger', 'Gradual change in inherited traits of a population over generations', 'Individual organisms changing during lifetime', 'C', 'Evolution happens to populations, not single individuals; traits pass across generations.', 'assets/illustrations/term1/t8_q1.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Who first proposed natural selection as the main mechanism of evolution?', 'Charles Darwin', 'Gregor Mendel', 'Antoine Lavoisier', 'Albert Einstein', 'A', 'Darwin published On the Origin of Species in 1859 based on Galápagos observations.', 'assets/illustrations/term1/t8_q2.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Natural selection is often summarized as:', 'Acquired life traits passed to offspring', 'Survival and reproduction of organisms BEST FITTED to environment', 'Only largest animals survive', 'Strongest always kill weakest', 'B', 'Fitness = ability to survive and produce fertile offspring, not just physical strength.', 'assets/illustrations/term1/t8_q3.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Any inherited trait helping an organism survive and reproduce is called:', 'Adaptation', 'Variation', 'Fossil', 'Isolation', 'A', 'Example: thick fur in polar bears, long necks in giraffes.', 'assets/illustrations/term1/t8_q4.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Natural differences in traits between individuals of the same species:', 'Selection', 'Heredity', 'Variation', 'Isolation', 'C', 'Variation must already exist in a population for natural selection to act on it.', 'assets/illustrations/term1/t8_q5.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Useful traits passed from parents to offspring is called:', 'Isolation', 'Variation', 'Adaptation', 'Heredity / Inheritance', 'D', 'Traits only affect evolution if they are genetic and can be inherited.', 'assets/illustrations/term1/t8_q6.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Preserved remains or traces of ancient organisms in rock layers:', 'Endemic species', 'Fossils', 'Adaptations', 'Homologous structures', 'B', 'Examples: bones, shells, footprints trapped in sedimentary rock.', 'assets/illustrations/term1/t8_q7.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Body parts with similar bone structure but different functions:', 'Vestigial structures', 'Fossils', 'Homologous structures', 'Analogous structures', 'C', 'Same basic plan = inherited from a common ancestor.', 'assets/illustrations/term1/t8_q8.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'A body part that lost most or all original function (e.g., human appendix):', 'Analogous', 'Adaptation', 'Homologous', 'Vestigial structure', 'D', 'Reduced in size; evidence of an ancestor that used it fully.', 'assets/illustrations/term1/t8_q9.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'The study of where different species live on Earth:', 'Genetics', 'Comparative anatomy', 'Paleontology', 'Biogeography', 'D', 'Explains why islands often have unique species found nowhere else.', 'assets/illustrations/term1/t8_q10.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Peppered moth turning dark during Industrial Revolution:', 'Biogeography', 'Artificial selection', 'Natural selection in action', 'Vestigial formation', 'C', 'Dark moths survived predation by birds better; reproduced more.', 'assets/illustrations/term1/t8_q11.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'A river splits a beetle population into two groups permanently:', 'Natural selection', 'Artificial selection', 'Reproductive isolation', 'Geographic isolation', 'D', 'Physical barrier separates populations; first step to speciation.', 'assets/illustrations/term1/t8_q12.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Bird wing and insect wing have same function but different structure:', 'Vestigial structures', 'Homologous structures', 'Fossils', 'Analogous structures', 'D', 'Same job, different origin = evolved independently, not from common ancestor.', 'assets/illustrations/term1/t8_q13.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Why is isolation important in forming NEW species?', 'It creates fossils faster', 'It increases mutation rate', 'It stops gene flow between groups, letting them evolve differently', 'It makes organisms weaker', 'C', 'Without contact, separated groups accumulate different traits.', 'assets/illustrations/term1/t8_q14.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Fossils found in deeper / older rock layers are generally:', 'Simpler and more different from living species today', 'Only large mammals', 'Identical to modern organisms', 'More complex than modern life', 'A', 'Fossil record shows simple life first, then gradual change over time.', 'assets/illustrations/term1/t8_q15.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Best evolutionary explanation for giraffes'' long necks:', 'Long-necked variants survived better and passed trait on', 'Random mutation made all necks long at once', 'Stretched to reach leaves and passed stretch to babies', 'All giraffes chose to grow longer necks', 'A', 'Variation existed first; natural selection favored longer necks over generations.', 'assets/illustrations/term1/t8_q16.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Farmers choosing largest, sweetest mangoes to plant:', 'Geographic isolation', 'Artificial selection', 'Vestigial selection', 'Natural selection', 'B', 'Humans, not nature, select which traits get passed on.', 'assets/illustrations/term1/t8_q17.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Early embryos of fish, chicken, pig, and human look similar:', 'DNA sequencing only', 'Comparative embryology', 'Fossil record', 'Biogeography', 'B', 'Shared early developmental stages inherited from a shared vertebrate ancestor.', 'assets/illustrations/term1/t8_q18.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Frogs in same pond mating at different months:', 'Geographic isolation', 'Analogous breeding', 'Reproductive isolation', 'Artificial selection', 'C', 'Behavioral/timing differences prevent mating; separate species.', 'assets/illustrations/term1/t8_q19.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Philippine Eagle found only in the Philippines:', 'An endemic species', 'An artificial species', 'A vestigial species', 'A fossil species', 'A', 'Biogeography: islands and isolated regions evolve unique endemic species.', 'assets/illustrations/term1/t8_q20.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Correct sequence of events for a new species to form (speciation):', 'Isolation → New species → Variation → Selection', 'New species → Variation → Isolation → Selection', 'Variation → Geographic Isolation → Natural Selection → Reproductive Isolation', 'Selection → Variation → Isolation → New species', 'C', 'Variation must exist first; separation stops gene flow; selection differentiates groups.', 'assets/illustrations/term1/t8_q21.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Why is natural selection considered the PRIMARY mechanism of evolution?', 'It was the first mechanism discovered', 'Only mechanism that CONSISTENTLY produces ADAPTATIONS matched to environment', 'It is the only mechanism that changes traits', 'It works instantly in one generation', 'B', 'Only natural selection reliably builds useful, environment-matched traits over time.', 'assets/illustrations/term1/t8_q22.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Modern whales have tiny unused pelvic bones. This shows:', 'Whales evolved from fish directly', 'Pelvic bone was always useless', 'Whales are still growing legs', 'Whales evolved from 4-legged land mammals moving back to sea', 'D', 'Fossil series confirms walking whale → semi-aquatic → fully aquatic whale.', 'assets/illustrations/term1/t8_q23.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Someone says: “Evolution is just a theory, so it’s just a guess.” Response:', 'In science, “theory” means well-tested explanation with massive evidence', 'Evolution is only a hypothesis', 'Theories become laws once proven', 'True, it has no evidence yet', 'A', 'Scientific theory ≠ casual guess; it is the highest level of scientific explanation.', 'assets/illustrations/term1/t8_q24.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Extinct reptile Mesosaurus fossils in S. America and Africa supports:', 'It evolved independently on both continents', 'Continental drift / Pangaea: continents once joined', 'The species swam across Atlantic Ocean', 'Fossils carried by humans', 'B', 'Key biogeography evidence: landmasses split and carried resident species.', 'assets/illustrations/term1/t8_q25.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Which is NOT a required condition for natural selection?', 'Traits acquired during life (e.g. big muscles) passed to offspring', 'Variation exists in population', 'Traits are heritable', 'More offspring born than can survive', 'A', 'Lamarck''s wrong idea; only genetic/inherited traits are passed on.', 'assets/illustrations/term1/t8_q26.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Homologous structures are strong evidence of common ancestry because:', 'They perform exact same function', 'They appear only in fossils', 'They share same unique bone arrangement from shared ancestor', 'They look identical externally', 'C', 'Same basic plan, different uses = descent with modification.', 'assets/illustrations/term1/t8_q27.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', '10-year drought leaves only large seeds; finch beak evolution will:', 'All finches instantly grow larger beaks', 'Average beak size will become LARGER, thicker, and stronger', 'Average beak size will get smaller', 'Beak size will not change', 'B', 'Birds with larger, stronger beaks survive and reproduce successfully.', 'assets/illustrations/term1/t8_q28.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Separated populations NOT isolated and individuals keep mating:', 'Mutations stop', 'Natural selection stops', 'Gene flow continues; they will NOT diverge into separate species', 'They become separate species', 'C', 'Constant mixing keeps gene pools similar; isolation is required for speciation.', 'assets/illustrations/term1/t8_q29.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Strongest, most reliable support for evolution by common descent:', 'Only DNA similarity alone', 'Only embryology alone', 'Fossil record + homologous structures + DNA similarity + biogeography agreeing', 'Only fossil record alone', 'C', 'Multiple independent lines of evidence converging make evolution extremely robust.', 'assets/illustrations/term1/t8_q30.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'What is the ultimate source of all genetic variation in a population?', 'Natural selection', 'Artificial selection', 'Mutations in DNA', 'Geographic isolation', 'C', 'Random mutations create entirely new alleles and genetic variations for selection to act upon.', 'assets/illustrations/term1/t8_q31.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Which evolutionary mechanism involves random changes in allele frequencies in small populations?', 'Natural selection', 'Genetic drift', 'Gene flow', 'Artificial selection', 'B', 'Genetic drift is random change due to chance events, especially significant in small populations.', 'assets/illustrations/term1/t8_q32.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'What term describes a sudden drastic reduction in population size due to a natural disaster?', 'Founder effect', 'Speciation', 'Bottleneck effect', 'Adaptive radiation', 'C', 'A bottleneck sharply reduces population size and genetic diversity randomly.', 'assets/illustrations/term1/t8_q33.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'How does the founder effect differ from the bottleneck effect?', 'Founder effect involves natural selection', 'Founder effect occurs when a few individuals colonize a new isolated habitat', 'Bottleneck effect only occurs in plants', 'There is no difference between them', 'B', 'The new colony carries only a fraction of the original population''s genetic diversity.', 'assets/illustrations/term1/t8_q34.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'What does molecular and DNA sequence comparison show among related species?', 'Unrelated species share identical DNA', 'Closely related species share greater DNA and protein sequence similarity', 'DNA changes randomly without pattern', 'Species do not share genetic codes', 'B', 'Greater genetic similarity reflects recent common ancestry.', 'assets/illustrations/term1/t8_q35.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'What is coevolution? Give a classic example.', 'Two species competing for identical food sources', 'Two species evolving in response to changes in each other (e.g., flowers and pollinators)', 'An organism evolving into two separate species', 'Species merging into one hybrid species', 'B', 'Reciprocal evolutionary adaptations occur between interacting species over time.', 'assets/illustrations/term1/t8_q36.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'What pattern of evolution occurs when unrelated species evolve similar traits due to similar environments?', 'Divergent evolution', 'Adaptive radiation', 'Convergent evolution', 'Coevolution', 'C', 'Unrelated organisms develop analogous structures (e.g., shark and dolphin fins) due to similar selective pressures.', 'assets/illustrations/term1/t8_q37.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'What pattern of evolution occurs when one species rapidly diversifies into many new forms (e.g., Darwin''s finches)?', 'Convergent evolution', 'Adaptive radiation', 'Stabilizing selection', 'Extinction', 'B', 'Rapid diversification occurs when species colonize new environments with vacant ecological niches.', 'assets/illustrations/term1/t8_q38.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'What is directional selection?', 'Selection favoring intermediate phenotypes', 'Selection favoring extremes at both ends', 'Selection favoring individuals at one extreme of a phenotypic range', 'Random elimination of phenotypes', 'C', 'Shifts population average trait value in one specific direction over time.', 'assets/illustrations/term1/t8_q39.svg', true),
  ('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Why do transitional fossils provide crucial evidence for evolutionary theory?', 'They prove species never change', 'They display intermediate traits connecting ancestral groups to modern descendants', 'They show life appeared everywhere simultaneously', 'They replace DNA evidence entirely', 'B', 'Transitional forms bridge evolutionary gaps, directly illustrating descent with modification.', 'assets/illustrations/term1/t8_q40.svg', true);
